+
+    #[test]
+    fn the_first_line_is_the_description() {
+        assert_eq!(
+            first_line(b"\n  tidy zsh aliases  \nmore\n").as_deref(),
+            Some("tidy zsh aliases")
+        );
+        assert_eq!(first_line(b"   \n"), None);
+        let long = "x".repeat(300);
+        assert_eq!(
+            first_line(long.as_bytes()).unwrap().len(),
+            DESCRIPTION_LIMIT
+        );
+    }
+}

